import{_ as s,o as n,c as t,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"第十一部分 · 信息论与编码","description":"","frontmatter":{},"headers":[],"relativePath":"info-theory/index.md","filePath":"info-theory/README.md","lastUpdated":1788475713000}'),m={name:"info-theory/index.md"};function l(p,a,i,r,o,c){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="第十一部分-·-信息论与编码" tabindex="-1">第十一部分 · 信息论与编码 <a class="header-anchor" href="#第十一部分-·-信息论与编码" aria-label="Permalink to &quot;第十一部分 · 信息论与编码&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>Shannon 1948 &quot;A Mathematical Theory of Communication&quot; 提出:<strong>信息 (information)</strong> 是可量化的——一个事件 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span> 的&quot;信息量&quot;<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><mo>−</mo><msub><mrow><mi>log</mi><mo>⁡</mo></mrow><mn>2</mn></msub><mi>P</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">I(x) = -\\log_2 P(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.207em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span> bits. 这条单公式衍生了三大主轴: <strong>(1) 信息压缩的极限 = 熵 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mo stretchy="false">(</mo><mi>X</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">H(X)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span></span></span></span></strong>; <strong>(2) 通信信道的极限 = 信道容量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi><mo>=</mo><mi>B</mi><msub><mrow><mi>log</mi><mo>⁡</mo></mrow><mn>2</mn></msub><mo stretchy="false">(</mo><mn>1</mn><mo>+</mo><mtext>SNR</mtext><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">C = B \\log_2(1+\\text{SNR})</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.207em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">SNR</span></span><span class="mclose">)</span></span></span></span></strong>; <strong>(3) 故障检测与纠正的极限 = 纠错码</strong>. 每一条都直接决定了我们今天的 5G NR 控制信道用 Polar 码 (Arikan 2008)、数据信道用 LDPC、4G 用 Turbo 码; QR 码 / SSD / RAID 6 / CD-ROM 用 Reed-Solomon; 软件压缩 zstd 用 LZ77 + ANS / Huffman encoder. 信息论既是理论与工程的桥梁, 也是物理定律 (信噪比的香农极限) 在数字通信上现实化.</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Streaming 4K HDR video over 5G mmWave]</span></span>
<span class="line"><span>  └─&gt; RAW: 12-bit × 7680×4320 × 60 Hz × 3 = 11.9 Gbit/s 原始比特流</span></span>
<span class="line"><span>       └─&gt; H.265 视频压缩 (intra + inter + DCT)</span></span>
<span class="line"><span>            └─&gt; ~25 Mbit/s (压缩比 ~500×)</span></span>
<span class="line"><span>                  └─&gt; 离熵 H(X): H.265 利用 spatial / temporal redundancy</span></span>
<span class="line"><span>                       └─&gt; 信道编码: 5G NR LDPC (data) / Polar code (control)</span></span>
<span class="line"><span>                             └─&gt; 添加 ~30% redundancy bit-rate 5/6</span></span>
<span class="line"><span>                                   └─&gt; QAM 调制: 64/256-QAM with constellation shaping</span></span>
<span class="line"><span>                                         └─&gt; OFDM: 100 MHz bandwidth, subcarriers 1200</span></span>
<span class="line"><span>                                               └─&gt; 香农极限: B log(1+SNR) = 100M × log₂(1+20) ≈ 432 Mbit/s</span></span>
<span class="line"><span>                                                     └─&gt; 实测 1.2 Gbit/s peak (with MIMO 4×4 spatial streams)</span></span>
<span class="line"><span>                                                           └─&gt; 距香农限不到 3 dB 实践范: SNR margin</span></span></code></pre></div><p>任何一层<strong>redundancy → entropy → coding → modulation</strong>, 每 error 从产业科学家 to 工程师逐环扣死. <strong>数学极限 vs 工业极限</strong>只有这个学科塞死了这条直游戏.</p><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><ul><li><a href="./">开篇：从 Shannon 1948 到 5G NR 编解码设计</a> ← 当前</li><li><a href="./entropy">1. Shannon Entropy: 离散源熵 / 联合熵 / 条件熵 / 互信息</a></li><li><a href="./capacity">2. 信道容量: 香农公式 C = B · log₂(1 + SNR)</a></li><li><a href="./compression">3. 无损压缩: 哈夫曼 / LZ77 / LZ78 / zstd / 算术编码 / ANS</a></li><li><a href="./hamming">4. 汉明码: 可纠 1-bit 错误的鼻祖</a></li><li><a href="./reed-solomon">5. Reed-Solomon 在 GF(2⁸) 上的纠错码</a></li><li><a href="./bch">6. BCH 码、循环码与多项式基础</a></li><li><a href="./ldpc">7. LDPC 码: 5G NR 数据信道与 Tanner 图</a></li><li><a href="./polar">8. Polar 码: Arikan 2008 构造与 5G NR 控制信道</a></li><li><a href="./turbo">9. Turbo 码: 3G/4G 并行级联卷积码与 BCJR 迭代</a></li><li><a href="./modulation">10. 调制: QPSK / 16-QAM / 64-QAM 星座图与误码率</a></li><li><a href="./appendix">附录: 编码率 / 纠错能力 / SNR 实践速查</a></li></ul><p>读完应能:</p><ol><li>给离散无记忆源 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>, 算熵 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mo stretchy="false">(</mo><mi>X</mi><mo stretchy="false">)</mo><mo>=</mo><mo>−</mo><mo>∑</mo><msub><mi>p</mi><mi>i</mi></msub><msub><mrow><mi>log</mi><mo>⁡</mo></mrow><mn>2</mn></msub><msub><mi>p</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">H(X) = -\\sum p_i \\log_2 p_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.207em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>; 给联合分布, 算 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mo stretchy="false">(</mo><mi>X</mi><mo separator="true">,</mo><mi>Y</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">H(X, Y)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mclose">)</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mo stretchy="false">(</mo><mi>X</mi><mi mathvariant="normal">∣</mi><mi>Y</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">H(X|Y)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mclose">)</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi><mo stretchy="false">(</mo><mi>X</mi><mo separator="true">;</mo><mi>Y</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">I(X;Y)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mclose">)</span></span></span></span>. 链式法则 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mo stretchy="false">(</mo><mi>X</mi><mo separator="true">,</mo><mi>Y</mi><mo stretchy="false">)</mo><mo>=</mo><mi>H</mi><mo stretchy="false">(</mo><mi>X</mi><mo stretchy="false">)</mo><mo>+</mo><mi>H</mi><mo stretchy="false">(</mo><mi>Y</mi><mi mathvariant="normal">∣</mi><mi>X</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">H(X, Y) = H(X) + H(Y|X)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.2222em;">Y</span><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span></span></span></span> 怎么从独立逐步推到条件.</li><li>说&quot;信源编码定理 (Shannon&#39;s source coding theorem)&quot;: 任何无损压缩的期望长度下界 ≥ <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mo stretchy="false">(</mo><mi>X</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">H(X)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span></span></span></span>. 例: 英语字母源熵 ~4.5 bits / char, ASCII 8 bits 过冗余度 ~44%.</li><li>香农容量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi><mo>=</mo><mi>B</mi><msub><mrow><mi>log</mi><mo>⁡</mo></mrow><mn>2</mn></msub><mo stretchy="false">(</mo><mn>1</mn><mo>+</mo><mi>S</mi><mi mathvariant="normal">/</mi><mi>N</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">C = B \\log_2(1 + S/N)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.207em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mclose">)</span></span></span></span> 推导: AWGN 信道下 high-SNR 渐近给出 ~<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><msub><mrow><mi>log</mi><mo>⁡</mo></mrow><mn>2</mn></msub><mtext>SNR</mtext></mrow><annotation encoding="application/x-tex">B \\log_2 \\text{SNR}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.9386em;vertical-align:-0.2441em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.207em;"><span style="top:-2.4559em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2441em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">SNR</span></span></span></span></span>. 实践 5G mmWave 上 100 MHz 带宽, 25 dB SNR ⇒ 理论 830 Mbit/s, 实测 5G 峰 1.4 Gbit/s (MIMO 4x4).</li><li>Huffman 编码本质 greedy 在频率上建前缀树, 但只能 approaching 整数 bit per symbol; 算术编码可以到分数 bit per symbol; ANS (Asymmetric Numeral Systems) 巧用进制 lattice 表搞出来 — zstd 生效.</li><li>汉明码 (7,4) 用奇偶校验矩阵 H 设计所进入=3 (Hu Porge), 单 e bit error recoverable; SECDED 加 1 个 overall parity bit 纠 1-bit + 检 2-bit.</li><li>Reed-Solomon (n, k) on GF(2^8) 用 generator polynomial <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>∏</mo><mo stretchy="false">(</mo><mi>x</mi><mo>−</mo><msup><mi>α</mi><mi>i</mi></msup><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\prod(x - \\alpha^i)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop op-symbol small-op" style="position:relative;top:0em;">∏</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.0747em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8247em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> for i = 1..(n-k); 修 erasure (CD / QR / SSD) 与错误 (TB Detect cord); RAID 6 双 RS-tolerant.</li><li>LDPC 用 sparse parity check matrix + Belief Propagation iterative decoder; complexity linear in n; design near-Shannon; 5G 数据信道选用. Tanner 图, girth ≥ 6.</li><li>Polar code (Arikan 2008) 用 channel polarization: fair split 与 unfair split, half 渐进无噪 / half 渐进全噪. 选择 &quot;good&quot; channels for data; &quot;frozen&quot; 部分固定.</li><li>Turbo 码: 2 RSC + interleaver + BCJR MAP decoder iterate; 3G/4G 起; 收敛速度劣于 LDPC, 5G 弃用 data 用 LDPC.</li><li>QPSK / 16-QAM / 64-QAM 的 constellation packing 定 bit/symbol; 与 SNR-coupled BER (QAM-64 在 21 dB SNR 下 BER ~10⁻⁵; coding 后 effective BER ~10⁻¹²).</li><li>现代卷积码 + Viterbi decoder; 5G 物理广播 channel (PBCH) 还在用 Polar; data 层 LDPC; LTE 在 turbo 主导 4G.</li></ol><h2 id="历史-1-1948-shannon-论文一锤定音" tabindex="-1">历史 1: 1948 Shannon 论文一锤定音 <a class="header-anchor" href="#历史-1-1948-shannon-论文一锤定音" aria-label="Permalink to &quot;历史 1: 1948 Shannon 论文一锤定音&quot;">​</a></h2><p>Claude Shannon 在 Bell System Technical Journal 发表 &quot;A Mathematical Theory of Communication&quot;, 引入 &quot;bit&quot; (binary digit) 概念, 区分信源 entropy vs 信道 capacity, 既给&quot;压缩极限&quot;又给&quot;通信极限&quot;. 这一 paper 同时建立&quot;信息论&quot;与&quot;编码论&quot;两个领域. 此前 Hartley 1928 给节 &quot;R = B log S&quot; 简易版本; Shannon 把统计级加入.</p><h2 id="历史-2-1950-hamming-7-4" tabindex="-1">历史 2: 1950 Hamming (7,4) <a class="header-anchor" href="#历史-2-1950-hamming-7-4" aria-label="Permalink to &quot;历史 2: 1950 Hamming (7,4)&quot;">​</a></h2><p>Richard Hamming 在 Bell Lab 与 Shannon 同时代, 因 weekends 实算 error bit 被后烦, 设计汉明码. 论文 1950 发, 第一 systematic error-correcting code. 直接 7 bit = 4 bit data + 3 bit parity, 单 bit 纠错. Hamming distance 概念 同引出.</p><h2 id="历史-3-1960-reed-solomon" tabindex="-1">历史 3: 1960 Reed-Solomon <a class="header-anchor" href="#历史-3-1960-reed-solomon" aria-label="Permalink to &quot;历史 3: 1960 Reed-Solomon&quot;">​</a></h2><p>Irving Reed 与 Gustave Solomon 在 MIT Lincoln Lab 给出 GF(2^m) 上 BCH 类码系统, 纠 erasure (data loss 已知位置)达 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi><mo>−</mo><mi>k</mi></mrow><annotation encoding="application/x-tex">n - k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>, 纠错误 (位置不知) 达 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">(</mo><mi>n</mi><mo>−</mo><mi>k</mi><mo stretchy="false">)</mo><mi mathvariant="normal">/</mi><mn>2</mn></mrow><annotation encoding="application/x-tex">(n-k)/2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">)</span><span class="mord">/2</span></span></span></span>. CD-ROM / DVD / QR / DSL 全部仍然在用. RS(255, 223) 给 16 字节 纠错: 这是空间探测器 Voyager / Galileo 上上行.</p><h2 id="历史-4-1993-berrou-turbo-码" tabindex="-1">历史 4: 1993 Berrou Turbo 码 <a class="header-anchor" href="#历史-4-1993-berrou-turbo-码" aria-label="Permalink to &quot;历史 4: 1993 Berrou Turbo 码&quot;">​</a></h2><p>Berrou-Glavieux-Thitimajshima 发表 &quot;Near Shannon limit error-correcting coding&quot; 在 ICC, 重写&quot;香农限&quot;概念——首次在 iteration 实验中观测到香农 ⼀≤ 1 dB. 业界就 quickly adopt 到 3G/4G 移动 communication 提出 consistency. 论文 originally 拒 paper from 1991 ICS conference on theory &#39;认为不&#39;are unworkable&#39;; final 来 1993 era takes broad acceptance 此 45-year Shannon limit 真类似.</p><h2 id="历史-5-1996-mackay-neal-ldpc-重发现" tabindex="-1">历史 5: 1996 MacKay-Neal LDPC 重发现 <a class="header-anchor" href="#历史-5-1996-mackay-neal-ldpc-重发现" aria-label="Permalink to &quot;历史 5: 1996 MacKay-Neal LDPC 重发现&quot;">​</a></h2><p>Gallager 1963 MIT dissertation 给 LDPC; 学术 default &#39;not practical&#39;; 1996 MacKay 与 Neal 重新发现 r 密度 sparse parity matrix + belief propagation iterative decoding → 给接近 Shannon 极限的性能, 业内对 LDPC &#39;re-embrace&#39;. DVB-S2 2003, WiFi 802.11n 2009, 5G NR 2016 data channel 用 LDPC 取代 Turbo.</p><h2 id="历史-6-2008-arikan-polar-码" tabindex="-1">历史 6: 2008 Arikan Polar 码 <a class="header-anchor" href="#历史-6-2008-arikan-polar-码" aria-label="Permalink to &quot;历史 6: 2008 Arikan Polar 码&quot;">​</a></h2><p>Erdal Arikan 在 Bilkent Univ 论 &quot;Channel Polarization&quot; 给出 deterministic code 接近 Shannon limit. 2016 3GPP RAN1 选择 Polar code 给 5G NR 控制信道 (短 message 短 coding). Polar 比 convolution/Turbo 在 short coding 给更显优势.</p><h2 id="历史-7-2014-2020-zstd-ans-brotli" tabindex="-1">历史 7: 2014-2020 zstd / ANS / Brotli <a class="header-anchor" href="#历史-7-2014-2020-zstd-ans-brotli" aria-label="Permalink to &quot;历史 7: 2014-2020 zstd / ANS / Brotli&quot;">​</a></h2><p>Jarek Duda 2006/2009 提出 ANS (Asymmetric Numeral Systems) 新编码 family, software 行 fast and throughput 化 entropy coding. Zstd Facebook 2015; Brotli Google 2015; LZ4 / zstd 给 现代压缩 pipeline (HTTP content-encoding br, zstd). BLAKE3 类作 hash + compression test drives equilibrium.</p><h2 id="历史-8-2009-2024-5g-nr-物理层标准化" tabindex="-1">历史 8: 2009-2024 5G NR 物理层标准化 <a class="header-anchor" href="#历史-8-2009-2024-5g-nr-物理层标准化" aria-label="Permalink to &quot;历史 8: 2009-2024 5G NR 物理层标准化&quot;">​</a></h2><p>3GPP Release 15 (2017-2018): 决策 LDPC for data (eMBB, long block sizes), Polar for control (short codes), 短 code 用 TBConv编码 legacy. Release 16-17 加入 URLLC 物理层 PID 极 support URLLC for industrial IoT; pilot channels Under non-3GPP RAN; ATIS RC 确上行 TX 按内 polar-coded.</p><hr><p>下一节 → <a href="./entropy">Shannon Entropy</a></p>`,28)])])}const d=s(m,[["render",l]]);export{g as __pageData,d as default};
